"use client";

import { useEffect, useRef, useState } from "react";
import {
  COMPUTER_KEYBOARD_OCTAVES,
  COMPUTER_KEYBOARD_VELOCITIES,
  controlOfKey,
  noteOfKey,
} from "@/lib/computer-keyboard";

const OCTAVES = [
  -COMPUTER_KEYBOARD_OCTAVES,
  COMPUTER_KEYBOARD_OCTAVES,
] as const;
const VELOCITY_RANGE = [0, COMPUTER_KEYBOARD_VELOCITIES.length - 1] as const;

const clamp = (value: number, [low, high]: readonly [number, number]) =>
  Math.max(low, Math.min(high, value));

/** Whether a key is not for the keyboard of notes: a repeat, a shortcut with Cmd, Ctrl or Alt, or typing into a field. */
function ignored(event: KeyboardEvent) {
  const element = event.target as HTMLElement | null;
  return (
    event.repeat ||
    event.metaKey ||
    event.ctrlKey ||
    event.altKey ||
    Boolean(
      element?.closest?.("input, textarea, select, [contenteditable=true]")
    )
  );
}

export interface UseComputerKeyboardOptions {
  /** Whether the keys play: off, they are the page's again. */
  enabled: boolean;
  onNoteOff: (note: number) => void;
  /** A key pressed: its note, and the velocity set with C and V, 0…1. */
  onNoteOn: (note: number, velocity: number) => void;
}

/**
 * Plays notes from the computer's keyboard while `enabled` (`noteOfKey`'s
 * layout): a key held is one note, released when the key is, or when the
 * keys are turned off or the window loses focus. Z and X move an octave, C
 * and V the velocity. Keys typed into a field, or held with Cmd, Ctrl or Alt,
 * are left alone.
 */
export function useComputerKeyboard({
  enabled,
  onNoteOff,
  onNoteOn,
}: UseComputerKeyboardOptions) {
  const [octave, setOctave] = useState(0);
  const [velocityIndex, setVelocityIndex] = useState(4);
  const handlers = useRef({ onNoteOff, onNoteOn });
  handlers.current = { onNoteOff, onNoteOn };
  const state = useRef({ octave, velocityIndex });
  state.current = { octave, velocityIndex };

  useEffect(() => {
    if (!enabled) {
      return;
    }
    // The note each key plays while it is held, so an octave changed under a held key still lets go of it.
    const held = new Map<string, number>();
    const releaseAll = () => {
      for (const note of held.values()) {
        handlers.current.onNoteOff(note);
      }
      held.clear();
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (ignored(event)) {
        return;
      }
      const change = controlOfKey(event.code);
      if (change) {
        event.preventDefault();
        if ("octave" in change) {
          setOctave((current) => clamp(current + change.octave, OCTAVES));
        } else {
          setVelocityIndex((current) =>
            clamp(current + change.velocity, VELOCITY_RANGE)
          );
        }
        return;
      }
      const note = noteOfKey(event.code, state.current.octave);
      if (note === null || held.has(event.code)) {
        return;
      }
      event.preventDefault();
      held.set(event.code, note);
      handlers.current.onNoteOn(
        note,
        COMPUTER_KEYBOARD_VELOCITIES[state.current.velocityIndex] ?? 0.8
      );
    };
    const onKeyUp = (event: KeyboardEvent) => {
      const note = held.get(event.code);
      if (note !== undefined) {
        held.delete(event.code);
        handlers.current.onNoteOff(note);
      }
    };
    window.addEventListener("keydown", onKeyDown);
    window.addEventListener("keyup", onKeyUp);
    window.addEventListener("blur", releaseAll);
    return () => {
      window.removeEventListener("keydown", onKeyDown);
      window.removeEventListener("keyup", onKeyUp);
      window.removeEventListener("blur", releaseAll);
      releaseAll();
    };
  }, [enabled]);

  return {
    /** Octaves from middle C, -4 to 4. */
    octave,
    /** The velocity a key plays at, 0…1. */
    velocity: COMPUTER_KEYBOARD_VELOCITIES[velocityIndex] ?? 0.8,
  };
}

/**
 * The computer's keyboard as a keyboard of notes, as in a DAW: the middle row
 * from A plays the white keys and the row above the black ones, Z and X move
 * an octave, C and V the velocity. Keys are read by where they sit
 * (`KeyboardEvent.code`), so the layout of letters does not move them.
 */

/** Semitones from the octave's C, by key. */
const NOTE_KEYS: Readonly<Record<string, number>> = {
  KeyA: 0,
  KeyW: 1,
  KeyS: 2,
  KeyE: 3,
  KeyD: 4,
  KeyF: 5,
  KeyT: 6,
  KeyG: 7,
  KeyY: 8,
  KeyH: 9,
  KeyU: 10,
  KeyJ: 11,
  KeyK: 12,
  KeyO: 13,
  KeyL: 14,
  KeyP: 15,
  Semicolon: 16,
  Quote: 17,
};

/** The keys that change the octave and the velocity. */
export const COMPUTER_KEYBOARD_CONTROLS = {
  octaveDown: "KeyZ",
  octaveUp: "KeyX",
  velocityDown: "KeyC",
  velocityUp: "KeyV",
} as const;

/** The C the A key plays at octave 0: middle C. */
export const COMPUTER_KEYBOARD_BASE = 60;

/** How far Z and X go, in octaves either way. */
export const COMPUTER_KEYBOARD_OCTAVES = 4;

/** The velocities C and V step through, 0…1. */
export const COMPUTER_KEYBOARD_VELOCITIES = [
  0.2, 0.35, 0.5, 0.65, 0.8, 1,
] as const;

/** The note a key plays at `octave`, or null for a key that plays none; null too past 0 and 127. */
export function noteOfKey(code: string, octave: number): number | null {
  const semitones = NOTE_KEYS[code];
  if (semitones === undefined) {
    return null;
  }
  const note = COMPUTER_KEYBOARD_BASE + octave * 12 + semitones;
  return note >= 0 && note <= 127 ? note : null;
}

/** What a control key changes, by how many steps: an octave (Z, X) or the velocity (C, V); null for any other key. */
export function controlOfKey(
  code: string
): { octave: number } | { velocity: number } | null {
  const controls = COMPUTER_KEYBOARD_CONTROLS;
  switch (code) {
    case controls.octaveDown:
      return { octave: -1 };
    case controls.octaveUp:
      return { octave: 1 };
    case controls.velocityDown:
      return { velocity: -1 };
    case controls.velocityUp:
      return { velocity: 1 };
    default:
      return null;
  }
}

/** Whether a key plays a note or changes the octave or the velocity: what the page's own shortcuts leave to the keyboard of notes. */
export function isComputerKeyboardKey(code: string): boolean {
  return (
    code in NOTE_KEYS ||
    (Object.values(COMPUTER_KEYBOARD_CONTROLS) as string[]).includes(code)
  );
}
